(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.35)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.28)*18+Math.sin(x*0.015+t*0.4)*12;
  const w2x = Math.sin(x*0.009+t*0.15)*25+Math.cos(y*0.007-t*0.1)*20;
  const w2y = Math.cos(y*0.008-t*0.12)*25+Math.sin(x*0.011+t*0.18)*20;
  const sx = x+w1x+w2x*0.5, sy = y+w1y+w2y*0.5;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*110, 160+Math.sin(t*0.7)*55, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.5+1)*95, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*85, 180+Math.sin(t*0.6+3)*65, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*95, 60+Math.cos(t*0.9+2)*75, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*130, 200+Math.sin(t*0.55)*85, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 1.15],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*45, 0.13, 1.8, 0.8],
    [200+Math.sin(t*0.25+6)*100, 30+Math.cos(t*0.45+3)*60, 0.05, 2.8, 1.2]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,w]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2,w2]=src[j];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross+=Math.sin(d*f+d2*f2-t*(sp+sp2)*0.5)*w*w2*0.15;
    }
  }
  const n=src.length;
  const act=aS/n, inh=iS/n, crs=cross/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07+t*1.8)*Math.sin(sy*0.06-t*1.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.025-ang*6-t*2.2)*0.2;
  const voro=()=>{
    let mn=99,d2=99;
    for(let i=0;i<5;i++){
      const vx=(Math.sin(t*0.3+i*1.25)*0.5+0.5)*480;
      const vy=(Math.cos(t*0.25+i*1.8)*0.5+0.5)*240;
      const vd=Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(vd<mn){d2=mn;mn=vd;}else if(vd<d2){d2=vd;}
    }
    return Math.sin(d2*0.15-t*1.5)*0.3;
  };
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral+crs)*2.2);
  const rd2=Math.tanh((rd1*0.8-inh*0.5+bg*0.15-voro())*2.5);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+Math.sin(sy*0.25+t*3)*2+t*4)*0.08;
  const blend=rd2*0.6+rd1*0.15+cell*0.2+micro, v=blend*0.5+0.5;
  const hShift=Math.sin(t*0.15)*0.08;
  const pal=[
    [6,12,58],[12,45,88],[18,95,115],[25,150,135],[180,190,75],
    [220,150,60],[200,100,70],[155,50,75],[90,25,65],[30,15,55],[6,12,58]
  ];
  const idx=Math.max(0,Math.min(v*(pal.length-1)+hShift,pal.length-1.001));
  const i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(rd2*Math.PI)*0.25;
  const edge=Math.abs(rd2)>0.65?1.2:Math.abs(rd2)>0.3?1.05:0.95;
  const glow=Math.max(0,rd2)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*30)|0)
  ];
}
